namespace Api.Web.FinanceIA.Models.Financia;

/// <summary>
/// EF Core entity that maps to [dbo].[AuditLogs].
/// Append-only audit trail — records are never updated or deleted.
/// </summary>
public sealed class AuditLog
{
    /// <summary>Primary key, auto-generated by the database.</summary>
    public long AuditLogId { get; set; }

    /// <summary>Tenant that owns this audit entry.</summary>
    public string TenantId { get; set; } = string.Empty;

    /// <summary>User who performed the action, or null for system-initiated events.</summary>
    public Guid? UserId { get; set; }

    /// <summary>
    /// Describes the action performed.
    /// Example values: User.Register, User.Login, User.PasswordChange.
    /// </summary>
    public string Action { get; set; } = string.Empty;

    /// <summary>Type of entity affected by the action.</summary>
    public string? EntityType { get; set; }

    /// <summary>Identifier of the entity affected by the action.</summary>
    public string? EntityId { get; set; }

    /// <summary>JSON snapshot of the entity state before the action.</summary>
    public string? OldValueJson { get; set; }

    /// <summary>JSON snapshot of the entity state after the action.</summary>
    public string? NewValueJson { get; set; }

    /// <summary>IP address of the client that initiated the action.</summary>
    public string? IpAddress { get; set; }

    /// <summary>ASP.NET Core request trace identifier for correlation.</summary>
    public string? RequestId { get; set; }

    /// <summary>Source system or component that generated the entry.</summary>
    public string? Source { get; set; }

    /// <summary>Severity of the event. Default: Info.</summary>
    public string Severity { get; set; } = "Info";

    /// <summary>UTC timestamp when the event occurred.</summary>
    public DateTime Timestamp { get; set; }
}
